from PIL import Image
import numpy as np
im = Image.open('hand-cannon.png').convert('RGB')
a = np.array(im).astype(int)
R,G,B = a[:,:,0], a[:,:,1], a[:,:,2]
blue = (B > G + 15) & (G > R + 8) & (B > 110)

def groups(idxs):
    gs=[]
    for i in idxs:
        if gs and i-gs[-1][-1]<=2: gs[-1].append(i)
        else: gs.append([i])
    return [(g[0],g[-1]) for g in gs]

print("Row scans (blue x-groups) x1380-1640:")
for y in range(190, 530, 4):
    xs = np.where(blue[y, 1380:1640])[0]+1380
    if len(xs): print(y, groups(list(xs)))
