import FreeCAD as App
import Part

doc = App.openDocument("/app/answer.FCStd")
sh = doc.getObject("HandCannon").Shape

def silhouette(axis):
    # axis: 'front' -> project along Y onto XZ ; 'top' -> project along Z onto XY
    out = set()
    if axis == 'front':
        # scan x,z ; ray along Y
        for ix in range(0, 163, 1):
            x = ix + 0.0
            for iz in range(-84, 34, 1):
                z = iz + 0.0
                ray = Part.makeLine(App.Vector(x, -60, z), App.Vector(x, 60, z))
                if sh.common(ray).Edges:
                    out.add((ix, iz))
        return out, 'x', 'z'
    else:
        for ix in range(0, 163, 1):
            x = ix + 0.0
            for iy in range(-32, 33, 1):
                y = iy + 0.0
                ray = Part.makeLine(App.Vector(x, y, -100), App.Vector(x, y, 60))
                if sh.common(ray).Edges:
                    out.add((ix, iy))
        return out, 'x', 'y'

for mode in ['front','top']:
    pts,_,_ = silhouette(mode)
    print("\n=== %s view ===" % mode)
    if mode=='front':
        xs = [p[0] for p in pts]; zs=[p[1] for p in pts]
        for z in range(33, -85, -2):
            row = ""
            for x in range(0, 163, 2):
                row += "#" if (x,z) in pts or (x+1,z) in pts or (x,z-1) in pts or (x+1,z-1) in pts else "."
            print("%4d %s" % (z, row))
    else:
        for y in range(32, -33, -2):
            row = ""
            for x in range(0, 163, 2):
                row += "#" if (x,y) in pts or (x+1,y) in pts or (x,y-1) in pts or (x+1,y-1) in pts else "."
            print("%4d %s" % (y, row))
EOF
freecadcmd /tmp/render.py 2>&1 | sed -n '/front view/,/top view/p' | head -62

