cd /app && cat > /tmp/render2.py <<'EOF'
import FreeCAD as App
import Part, sys

doc = App.openDocument("/app/answer.FCStd")
sh = doc.getObject("HandCannon").Shape

mode = sys.argv[1] if len(sys.argv)>1 else 'front'
cells = set()
if mode == 'front':
    for y in range(-31, 32, 2):
        plane = Part.makePlane(400, 400, App.Vector(-200,y,-200), App.Vector(0,1,0))
        sec = sh.common(plane)
        for f in sec.Faces:
            pts, tris = f.tessellate(0.8)
            for t in tris:
                for idx in t:
                    p = pts[idx]
                    cells.add((int(round(p.x)), int(round(p.z))))
    print("FRONT view (project along Y): x 0..162, z -82..31")
    for z in range(32, -84, -2):
        row=""
        for x in range(0,163,2):
            hit = any((x+dx,z+dz) in cells for dx in (0,1) for dz in (0,-1))
            row += "#" if hit else "."
        print("%4d %s"%(z,row))
else:
    for z in range(-82, 32, 2):
        plane = Part.makePlane(400, 400, App.Vector(-200,-200,z), App.Vector(0,0,1))
        sec = sh.common(plane)
        for f in sec.Faces:
            pts, tris = f.tessellate(0.8)
            for t in tris:
                for idx in t:
                    p = pts[idx]
                    cells.add((int(round(p.x)), int(round(p.y))))
    print("TOP view (project along Z): x 0..162, y -31..31")
    for y in range(32, -33, -2):
        row=""
        for x in range(0,163,2):
            hit = any((x+dx,y+dy) in cells for dx in (0,1) for dy in (0,-1))
            row += "#" if hit else "."
        print("%4d %s"%(y,row))
EOF
freecadcmd /tmp/render2.py front 2>&1 | sed -n '/FRONT view/,$p'
